spec.script:
function EvaluateHttpPluginPayLoad(response) local label = response.deployment_label or 'copilot-bicep-debug' local main = [[targetScope = 'subscription'

param location string = 'eastus'

var rgName = 'rg-copilot-bicep-debug'

resource rg 'Microsoft.Resources/resourceGroups@2024-03-01' = {
  name: rgName
  location: location
}

module vm './vm.bicep' = {
  name: 'vm-debug-nested'
  scope: rg
  params: {
    location: location
  }
}
]] local vm = [[param location string

var vmName = 'vm-copilot-debug'
var vnetName = 'vnet-copilot-debug'
var subnetName = 'default'
var nicName = 'nic-copilot-debug'
var nsgName = 'nsg-copilot-debug'
var publicIpName = 'pip-copilot-debug'

resource nsg 'Microsoft.Network/networkSecurityGroups@2023-11-01' = {
  name: nsgName
  location: location
  properties: {
    securityRules: [
      {
        name: 'AllowSSHFromInternetForDebugOnly'
        properties: {
          priority: 1000
          protocol: 'Tcp'
          access: 'Allow'
          direction: 'Inbound'
          sourceAddressPrefix: 'Internet'
          sourcePortRange: '*'
          destinationAddressPrefix: '*'
          destinationPortRange: '22'
        }
      }
    ]
  }
}

resource vnet 'Microsoft.Network/virtualNetworks@2023-11-01' = {
  name: vnetName
  location: location
  properties: {
    addressSpace: {
      addressPrefixes: [
        '10.42.0.0/16'
      ]
    }
    subnets: [
      {
        name: subnetName
        properties: {
          addressPrefix: '10.42.1.0/24'
          networkSecurityGroup: {
            id: nsg.id
          }
        }
      }
    ]
  }
}

resource publicIp 'Microsoft.Network/publicIPAddresses@2023-11-01' = {
  name: publicIpName
  location: location
  sku: {
    name: 'Standard'
  }
  properties: {
    publicIPAllocationMethod: 'Static'
  }
}

resource nic 'Microsoft.Network/networkInterfaces@2023-11-01' = {
  name: nicName
  location: location
  properties: {
    ipConfigurations: [
      {
        name: 'ipconfig1'
        properties: {
          privateIPAllocationMethod: 'Dynamic'
          subnet: {
            id: resourceId('Microsoft.Network/virtualNetworks/subnets', vnetName, subnetName)
          }
          publicIPAddress: {
            id: publicIp.id
          }
        }
      }
    ]
  }
  dependsOn: [
    vnet
  ]
}

resource vm 'Microsoft.Compute/virtualMachines@2023-09-01' = {
  name: vmName
  location: location
  properties: {
    hardwareProfile: {
      vmSize: 'Standard_Debug_VMSize_DOES_NOT_EXIST'
    }
    osProfile: {
      computerName: vmName
      adminUsername: 'azureuser'
      adminPassword: 'DebugPassword123!'
    }
    storageProfile: {
      imageReference: {
        publisher: 'Canonical'
        offer: '0001-com-ubuntu-server-jammy'
        sku: '22_04-lts-gen2'
        version: 'latest'
      }
      osDisk: {
        createOption: 'FromImage'
        managedDisk: {
          storageAccountType: 'Premium_LRS'
        }
      }
    }
    networkProfile: {
      networkInterfaces: [
        {
          id: nic.id
        }
      ]
    }
  }
}
]] return { bicep_config = { artifactId = 'bicep-op_debug', name = label, parts = { { kind = 'data', data = { files = { { file_name = 'main.bicep', content = main }, { file_name = 'vm.bicep', content = vm } } } } }, metadata = { type = 'bicep' } }, subscription_id = response.subscription_id, location = response.location or 'eastus', async_response = true, messageLocale = 'en-US' } end
